 await expect(page.getByLabel('产品类型',{exact:true})).toHaveValue('洁面')
 await expect(page.getByLabel('开封日期',{exact:true})).toBeVisible()
 await expect(page.getByText('你说的「12个月」具体指什么？',{exact:true})).toBeVisible()
 await expect(page.locator('#photo')).toHaveCount(0)
 await page.getByRole('button',{name:'保存，结束整理',exact:true}).click()
 await expect(page.getByRole('alert')).toContainText('请确认')
