 const r=await page.evaluate(()=>JSON.parse(localStorage.getItem('dpao_review_prototype_v1'))[0])
 expect(r.name).toBe('悦诗风吟洗面奶');expect(r.months).toBe(12);expect(r.rawInput).toBe(raw);expect(r.durationDisposition).toBe('opened')
