 await page.getByRole('button',{name:'一句话录入',exact:true}).click();await page.getByLabel('一句话描述').fill('今天开了瓶洗面奶，悦诗风吟，写了12个月')
 await page.getByRole('button',{name:'提取信息，先让我确认'}).click()
